 using(var bitmap=new SKBitmap(2,2,SKColorType.Rgba8888,SKAlphaType.Unpremul)){for(var y=0;y<2;y++)for(var x=0;x<2;x++)bitmap.SetPixel(x,y,new SKColor(0,255,0,(byte)(17+x+y*2)));using var image=SKImage.FromBitmap(bitmap);using var data=image.Encode(SKEncodedImageFormat.Png,100);File.WriteAllBytes(png,data.ToArray());}
